CREATE TABLE "tblDispute"
(
    "Id"            BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ExternalId"    UUID                                    NOT NULL,
    "CustomerId"    BIGINT                                  NOT NULL,
    "TransactionId" BIGINT                                  NOT NULL,
    "Reason"        VARCHAR(100)                            NOT NULL,
    "Explanation"   VARCHAR(500)                            NULL,
    "Status"        VARCHAR(100)                            NOT NULL,
    "CreatedAt"     TIMESTAMP WITH TIME ZONE                NOT NULL,
    "UpdatedAt"     TIMESTAMP WITH TIME ZONE                NOT NULL,

    CONSTRAINT "PK_Dispute" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_Dispute_ExternalId" UNIQUE ("ExternalId"),
    CONSTRAINT "FK_Dispute_Customer" FOREIGN KEY ("CustomerId") REFERENCES "tblCustomer" ("Id"),
    CONSTRAINT "FK_Dispute_Transaction" FOREIGN KEY ("TransactionId") REFERENCES "tblTransaction" ("Id")
);

CREATE INDEX "IX_Dispute_CustomerIdCreatedAtId" ON "tblDispute" ("CustomerId", "CreatedAt" DESC, "Id" DESC);

CREATE UNIQUE INDEX "UQ_Dispute_CustomerIdTransactionId_Active"
    ON "tblDispute" ("CustomerId", "TransactionId")
    WHERE "Status" IN ('Submitted', 'UnderReview');
